package org.novasos.healthysv2.laboratory;
import static org.novasos.healthysv2.laboratory.api.LaboratoryDtos.*;import java.net.*;import java.util.*;import jakarta.validation.Valid;import io.swagger.v3.oas.annotations.tags.Tag;import org.novasos.healthysv2.shared.api.ApiPaths;import org.novasos.healthysv2.shared.api.dto.PageResponse;import org.springframework.data.domain.Pageable;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping(ApiPaths.V1+"/lab-orders") @Tag(name="Laboratory",description="Laboratory orders, specimens and results workflow") @PreAuthorize("hasAnyRole('PLATFORM_ADMIN','HOSPITAL_ADMIN','DOCTOR','NURSE','LAB_TECHNICIAN')") class LaboratoryController{
 private static final String ORDER="hasAnyRole('PLATFORM_ADMIN','HOSPITAL_ADMIN','DOCTOR')",LAB="hasAnyRole('PLATFORM_ADMIN','HOSPITAL_ADMIN','LAB_TECHNICIAN')";private final LaboratoryService service;LaboratoryController(LaboratoryService service){this.service=service;}
 @PostMapping @PreAuthorize(ORDER)ResponseEntity<LabOrderResponse>create(@Valid@RequestBody CreateOrderRequest r){var out=service.create(r);return ResponseEntity.created(URI.create(ApiPaths.V1+"/lab-orders/"+out.id())).body(out);}@GetMapping("/{id}")LabOrderResponse find(@PathVariable UUID id){return service.find(id);}@GetMapping PageResponse<OrderSummary>search(@RequestParam(required=false)UUID patientId,@RequestParam(required=false)UUID organizationId,@RequestParam(required=false)String status,Pageable pageable){return service.search(patientId,organizationId,status,pageable);}@PostMapping("/{id}/items")@PreAuthorize(ORDER)ResponseEntity<LabOrderItemResponse>addItem(@PathVariable UUID id,@Valid@RequestBody OrderItemRequest r){return ResponseEntity.status(201).body(service.addItem(id,r));}
 @PostMapping("/{order}/items/{item}/specimens")@PreAuthorize(LAB)ResponseEntity<SpecimenResponse>collect(@PathVariable UUID order,@PathVariable UUID item,@Valid@RequestBody CollectSpecimenRequest r){return ResponseEntity.status(201).body(service.collect(order,item,r));}@PostMapping("/{order}/specimens/{specimen}/receive")@PreAuthorize(LAB)SpecimenResponse receive(@PathVariable UUID order,@PathVariable UUID specimen){return service.receive(order,specimen);}@PostMapping("/{order}/specimens/{specimen}/reject")@PreAuthorize(LAB)SpecimenResponse reject(@PathVariable UUID order,@PathVariable UUID specimen){return service.reject(order,specimen);}
 @PostMapping("/{order}/results")@PreAuthorize(LAB)ResponseEntity<LabResultResponse>result(@PathVariable UUID order,@Valid@RequestBody CreateResultRequest r){return ResponseEntity.status(201).body(service.createResult(order,r));}@PostMapping("/{order}/results/{result}/items")@PreAuthorize(LAB)ResponseEntity<LabResultItemResponse>resultItem(@PathVariable UUID order,@PathVariable UUID result,@Valid@RequestBody ResultItemRequest r){return ResponseEntity.status(201).body(service.addResultItem(order,result,r));}@PostMapping("/{order}/results/{result}/validate")@PreAuthorize(LAB)LabResultResponse validate(@PathVariable UUID order,@PathVariable UUID result,@Valid@RequestBody ValidateResultRequest r){return service.validate(order,result,r);}@PostMapping("/{id}/cancel")@PreAuthorize(ORDER)LabOrderResponse cancel(@PathVariable UUID id){return service.cancel(id);}
}
